import os
for root, dirs, files in os.walk('/workspace'):
    # prune memory
    dirs[:] = [d for d in dirs if d not in ('memory', '.prompts', '__pycache__', '.git')]
    depth = root.count('/') - 1
    if depth > 4: continue
    for f in files:
        p = os.path.join(root, f)
        try:
            sz = os.path.getsize(p)
        except OSError:
            sz = -1
        print(p, sz)

